function validate([nums, queries]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value of nums is an integer from 1 to 10^5.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2 || !query.every(Number.isInteger)) return 'Each query is a pair [from, to].';
    if (query[0] < 0 || query[0] > query[1] || query[1] >= nums.length) return 'Each query needs 0 <= from <= to <= nums.length - 1.';
  }
  return null;
}

