function isArraySpecial(nums, queries) {
  // bad[i] counts the neighbouring pairs with equal parity inside nums[0..i].
  const bad = new Array(nums.length).fill(0);
  for (let i = 1; i < nums.length; i++) {
    bad[i] = bad[i - 1];
    if (nums[i] % 2 === nums[i - 1] % 2) {
      bad[i]++;
    }
  }
  const answer = [];
  for (const [from, to] of queries) {
    const badPairs = bad[to] - bad[from];
    answer.push(badPairs === 0);
  }
  return answer;
}

