function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const valueWithParity = (parity, top) => {
    const v = int(1, top);
    if (v % 2 === parity) return v;
    return v === top ? v - 1 : v + 1;
  };
  const large = size === 'large';
  const n = large ? 2000 : int(1, 9);
  const top = large ? 100000 : rand() < 0.5 ? 10 : 100000;
  // Mostly alternating parity, broken now and then, so that both answers are common.
  const breakChance = large ? [0.002, 0.01, 0.05][int(0, 2)] : [0, 0.15, 0.4, 1][int(0, 3)];
  const nums = [];
  let parity = int(0, 1);
  for (let i = 0; i < n; i++) {
    if (i > 0 && rand() >= breakChance) parity = 1 - parity;
    nums.push(valueWithParity(parity, top));
  }
  const count = large ? 2000 : int(1, 6);
  const queries = [];
  for (let q = 0; q < count; q++) {
    const from = int(0, n - 1);
    // Short, medium and long ranges, including single elements.
    const span = [0, int(0, 3), int(0, 40), n][int(0, 3)];
    queries.push([from, Math.min(n - 1, from + span)]);
  }
  return [nums, queries];
}
